def strange_sort_list(lst):
    if not lst:
        return []

    lst_sorted = sorted(lst)
    result = []

    while lst_sorted:
        result.append(lst_sorted.pop(0))  # Append the minimum
        if lst_sorted:
            result.append(lst_sorted.pop(-1))  # Append the maximum

    return result
